# build_truly_diverse_catalog.ps1
# Generates 530 genuinely distinct products spanning 23 departments with unique images and descriptions.
$ErrorActionPreference = "Stop"

$allProducts = [System.Collections.Generic.List[hashtable]]::new()

function Add-P {
    param($id, $sId, $sName, $cat, $name, $desc, $price, $stock, $r, $rev, $img)
    $allProducts.Add(@{
        id = $id; sId = $sId; sName = $sName; cat = $cat; name = $name;
        desc = $desc; price = [double]$price; stock = [int]$stock;
        r = [double]$r; rev = [int]$rev; img = $img
    })
}

